function findSubstringInWraproundString(s) {
  const longest = new Array(26).fill(0);
  let run = 0;

  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i) - 97;
    if (i > 0 && (s.charCodeAt(i - 1) - 97 + 1) % 26 === code) {
      run++;
    } else {
      run = 1;
    }
    longest[code] = Math.max(longest[code], run);
  }

  let total = 0;
  for (const length of longest) {
    total += length;
  }
  return total;
}

