function findSubstringInWraproundString(s) {
  // Collect every substring whose neighbouring letters follow the alphabet (with z -> a).
  const found = new Set();
  for (let a = 0; a < s.length; a++) {
    for (let b = a + 1; b <= s.length; b++) {
      const piece = s.slice(a, b);
      let ok = true;
      for (let k = 1; k < piece.length; k++) {
        const want = piece[k - 1] === 'z' ? 'a' : String.fromCharCode(piece.charCodeAt(k - 1) + 1);
        if (piece[k] !== want) ok = false;
      }
      if (ok) found.add(piece);
    }
  }
  return found.size;
}

