function generate(rand, size) {
  const letter = code => String.fromCharCode(97 + ((code % 26) + 26) % 26);
  const target = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const style = rand();
  let s = '';
  while (s.length < target) {
    if (style < 0.25) {
      // Random letters from a small alphabet near the wrap point.
      s += letter(23 + Math.floor(rand() * 6));
      continue;
    }
    // A run of consecutive letters, possibly wrapping past 'z'.
    const start = Math.floor(rand() * 26);
    const maxRun = size === 'large' ? (style < 0.6 ? 30 : 400) : 8;
    const length = 1 + Math.floor(rand() * maxRun);
    for (let k = 0; k < length && s.length < target; k++) s += letter(start + k);
  }
  return [s];
}
